from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            if key in cache:
                _, wt = cache[key]
                if t >= wt + ttl:
                    # expired, remove it
                    del cache[key]

            if key in cache:
                # still present (not expired), update value, write time, move to end
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                # need to insert new entry
                if len(cache) >= capacity:
                    # evict LRU
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)

        elif kind == 'get':
            if key in cache:
                val, wt = cache[key]
                if t >= wt + ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(val)
                    cache.move_to_end(key)
            else:
                results.append(-1)

    return results

